import sys
from math import ceil

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    operations = []
    index = 2
    for _ in range(n):
        t = int(input[index])
        x = float(input[index + 1]) / 100000
        y = int(input[index + 2])
        operations.append((t, x, y))
        index += 3

    result = [-1] * m
    dp = [float('inf')] * (m + 1)
    dp[0] = 0

    for step in range(1, n + 1):
        t, x, y = operations[step - 1]
        if t == 1:
            for k in range(m, -1, -1):
                for a in range(y + 1):
                    if k + a * x <= m:
                        dp[k + a * x] = min(dp[k + a * x], dp[k] + a)
        elif t == 2:
            for k in range(m, -1, -1):
                if dp[k] < float('inf'):
                    for a in range(y + 1):
                        nk = ceil(k * (x ** a))
                        if nk <= m:
                            dp[nk] = min(dp[nk], dp[k] + a)

    for j in range(1, m + 1):
        if dp[j] <= n:
            result[j - 1] = dp[j]

    print(" ".join(map(str, result)))

main()
